// overleaf-lab: signals compatible with machine-generated text, counted in code.
//
// WHAT THIS IS NOT. It is not a detector. There is no classifier here, no probability,
// no model call, and no field anywhere in the output that could be read as a verdict.
// The published evaluations of the commercial detectors are the reason: 61.3% of
// TOEFL essays written by human non-native speakers were called AI-generated by the
// detectors tested (Liang et al.), because those detectors key on low perplexity and a
// second-language writer writes with a smaller vocabulary and simpler sentences. A
// university that acts on that number expels the students who had the hardest time
// writing the thesis. So this module counts things and shows the passages; a human
// reads them and decides, or decides there is nothing to decide.
//
// PHASE 1 IS CODE ONLY. Deterministic, no LLM call, no network, no I/O: pure
// functions over text the review already assembled. It costs nothing to run and it
// runs the same way twice, which is what makes a stored report comparable with the
// next one.
//
// THE ANTI-FALSE-POSITIVE CORE: THE THESIS IS ITS OWN BASELINE. No style signal has an
// absolute threshold, because there is no honest one: em-dash density, sentence-length
// variance and stock phrasing all vary by field, by supervisor and by native language,
// and any fixed cut-off is a cut-off against a population this document may not belong
// to. What CAN be said is that one chapter does not read like the rest of the same
// thesis. So every signal is computed per chapter and compared against the MEDIAN of
// the chapters of this document, two-tailed, on a robust scale (median absolute
// deviation), and nothing is flagged unless there are at least four chapters to build
// that baseline from. A thesis written entirely by a model has a flat baseline and
// flags nothing here, which is a known and accepted limit: this section is for the
// reader who wants to know where to look, not for a machine that decides.
//
// The second reporting path is local and needs no baseline: a single PARAGRAPH holding
// three or more DISTINCT stock markers. One marker is a word somebody likes; three in
// one paragraph is a register. Single hits are never reported, anywhere.
//
// Artifacts are the exception to all of the above and are always reported. They are
// not style, they are debris left by a chat interface.

import {
    AI_SIGNAL_PATTERNS_VERSION,
    LEXICAL_PATTERNS,
    SENTENCE_OPENERS,
    ARTIFACT_PATTERNS,
} from './ai-signal-patterns.mjs'

export const AI_SIGNALS_VERSION = AI_SIGNAL_PATTERNS_VERSION

// overleaf-lab: at least this many chapters before any style signal may be flagged.
// Below it the median IS the outlier: with three chapters, one deviating chapter moves
// the median it is being compared against.
export const MIN_CHAPTERS_FOR_BASELINE = 4

// overleaf-lab: a chapter shorter than this does not take part in the baseline and is
// never flagged by it. A 40-word front matter page has a sentence-length variance that
// means nothing, and letting it into the median drags the baseline of the chapters
// that do carry prose.
export const MIN_CHAPTER_WORDS = 150

// overleaf-lab: how far from the median a chapter has to sit. Distance is measured in
// median absolute deviations, which is the point: a mean and a standard deviation are
// moved by the very chapter under test, a median and a MAD are not.
export const ROBUST_SCORE_THRESHOLD = 3

// overleaf-lab: distinct markers in ONE paragraph before it is called a cluster.
export const CLUSTER_MIN_MARKERS = 3

// overleaf-lab: bounds on what is STORED, never on what is counted.
//
// Two reasons, and the second is the one that bites. A report nobody finishes reading
// protects nobody. And this block is written into the job result, into the Mongo
// document the dashboard reads and into the archived HTML: a thesis pasted out of a
// word processor carries thousands of typographic quotes, and one unbounded list turns
// a 20 KB report into a megabyte in three places at once.
//
// NO SILENT CAPS. Every capped list is stored next to the true total, the counting
// always runs over the whole text, and the report says "showing the first N of M". A
// cap the reader cannot see is a lie about how much was found.
const MAX_EXCERPT_CHARS = 160
const MAX_EXCERPTS_PER_SIGNAL = 5
const MAX_CLUSTERS = 20
const MAX_CLUSTER_MARKERS = 8
const MAX_ARTIFACT_ROWS = 30
// A ceiling on the whole flagged-chapter table rather than on the chapters alone: one
// chapter flagged on eight signals and eight chapters flagged on one each cost the same
// to store, and it is the number of signal rows that decides the size of the block.
const MAX_FLAGGED_SIGNALS = 30

// The numbers above, exported so a test can assert against the shipped values rather
// than against a copy of them.
export const LIMITS = {
    excerptChars: MAX_EXCERPT_CHARS,
    excerptsPerSignal: MAX_EXCERPTS_PER_SIGNAL,
    clusters: MAX_CLUSTERS,
    clusterMarkers: MAX_CLUSTER_MARKERS,
    artifactRows: MAX_ARTIFACT_ROWS,
    flaggedSignals: MAX_FLAGGED_SIGNALS,
}

// ---------------------------------------------------------------------------
// pattern compilation
// ---------------------------------------------------------------------------

// overleaf-lab: compile a pattern list, dropping anything that does not compile rather
// than taking the whole review down with it. The `u` flag is not optional: the guards
// in the pattern sources are unicode property escapes, which only exist under it.
export function compilePatterns(entries) {
    const compiled = []
    for (const entry of entries || []) {
        try {
            compiled.push({ ...entry, regex: new RegExp(entry.source, 'giu') })
        } catch {
            // A malformed default is a bug in the data file, not a reason to lose the
            // review; the test suite is what stops one shipping.
        }
    }
    return compiled
}

const LEXICAL = compilePatterns(LEXICAL_PATTERNS)
const ARTIFACTS = compilePatterns(ARTIFACT_PATTERNS)

const OPENER_PATTERN = new RegExp(
    `^(?:${SENTENCE_OPENERS.map(o => o.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+')).join('|')})(?![\\p{L}\\p{N}])`,
    'iu'
)

// ---------------------------------------------------------------------------
// text preparation
// ---------------------------------------------------------------------------

// Environments whose body is not prose. Counting their lines as sentences turned a
// chapter with one long table into the most "uniform" chapter in the document.
const NON_PROSE_ENVIRONMENTS =
    'verbatim|lstlisting|minted|Verbatim|tikzpicture|tabular[*xy]?|tabularx|longtable|align[*]?|equation[*]?|gather[*]?|multline[*]?|thebibliography|filecontents[*]?'

// Commands whose braced argument is a key, a path or a number, never text to read.
const NON_PROSE_COMMANDS =
    'cite[a-zA-Z]*|[Cc]ref[a-zA-Z]*|ref|pageref|eqref|label|includegraphics|input|include|usepackage|documentclass|bibliography[a-zA-Z]*|url|href|nocite|autoref|hypersetup|setlength|newcommand|renewcommand|acro|gls[a-zA-Z]*'

// overleaf-lab: blank a set of spans with ONE rebuild of the string.
//
// The obvious loop - slice, join, repeat, once per span - copies the whole chapter for
// every span, which is the same quadratic by another door. Ranges must arrive sorted by
// start; one that opens inside a range already taken is dropped, which is what makes a
// nested environment blanked by its parent alone.
//
// The span becomes a single space rather than a run of spaces: this module compares
// chapters against each other and never reports a line number, so offsets are worth
// nothing here and the shorter string is cheaper to tokenize.
function replaceRanges(text, ranges) {
    if (ranges.length === 0) {
        return text
    }
    const pieces = []
    let cursor = 0
    for (const [start, end] of ranges) {
        if (start < cursor || end <= start) {
            continue
        }
        pieces.push(text.slice(cursor, start), ' ')
        cursor = end
    }
    pieces.push(text.slice(cursor))
    return pieces.join('')
}

// overleaf-lab: the non-prose environments, found in ONE pass with a stack per name.
//
// This replaces `\begin{X}[\s\S]*?\end{X}`, which is quadratic the moment an \end is
// missing: the lazy body scans to the end of the file, fails, and the engine retries
// from the next \begin, so M unclosed opens over n bytes cost O(M*n) and M grows with n.
// Measured on this module before the rewrite, on one chapter of `\begin{align}` with no
// \end: 1600 opens 101 ms, 6400 opens (825 KB) 1180 ms, extrapolating to about five
// seconds on a 2 MB chapter - synchronous, inside the request, at the end of every
// review, from one file a student pasted. The two other modules that walk LaTeX were
// rewritten for exactly this; this call site had been left behind.
//
// A THIRD LOCAL COPY of a scan the tree already has twice, for the reason
// LLMLanguageTool.mjs writes down next to its own: the structural checks module is the
// reference implementation but it is loaded with a report language and a catalogue of
// checks this file has no business touching, and the subset needed here is twenty lines.
// Where the copies disagree, the structural checks are the reference.
//
// An UNTERMINATED environment blanks nothing, which is what the regex did too and is the
// safe side: stretching it to the end of the file would delete prose the author wrote,
// and the counts would then describe a document nobody handed in.
const ENVIRONMENT_TOKEN = String.raw`\\(begin|end)\{(${NON_PROSE_ENVIRONMENTS})\}`

function blankNonProseEnvironments(text) {
    const token = new RegExp(ENVIRONMENT_TOKEN, 'g')
    const open = new Map()
    const ranges = []
    let match
    while ((match = token.exec(text)) !== null) {
        // Paired on the exact name, star included, exactly as the backreference in the
        // old pattern paired them: \begin{align*} is not closed by \end{align}.
        const name = match[2]
        if (match[1] === 'begin') {
            if (!open.has(name)) {
                open.set(name, [])
            }
            open.get(name).push(match.index)
            continue
        }
        const stack = open.get(name)
        // An \end with no \begin is a broken document, not an environment: ignored.
        if (stack && stack.length > 0) {
            ranges.push([stack.pop(), match.index + match[0].length])
        }
    }
    // Innermost pairs close first, so the ranges come out of the scan unordered.
    ranges.sort((a, b) => a[0] - b[0])
    return replaceRanges(text, ranges)
}

// overleaf-lab: display maths, as one pass over the DELIMITERS. `\\\[[\s\S]*?\\\]` has
// the same shape and the same failure as the environment pattern above: a chapter of
// `\[` that never closes rescans to the end of the file once per opener. Paired here
// instead, with an opener that finds no closer blanking nothing, as above.
const MATH_DELIMITER = /\$\$|\\\[|\\\]/g

function blankDisplayMaths(text) {
    const token = new RegExp(MATH_DELIMITER.source, 'g')
    const ranges = []
    let start = -1
    let closer = ''
    let match
    while ((match = token.exec(text)) !== null) {
        if (start < 0) {
            // A closer with nothing open is stray markup, not a span.
            if (match[0] === '\\]') {
                continue
            }
            start = match.index
            closer = match[0] === '$$' ? '$$' : '\\]'
            continue
        }
        if (match[0] !== closer) {
            continue
        }
        ranges.push([start, match.index + match[0].length])
        start = -1
    }
    return replaceRanges(text, ranges)
}

// overleaf-lab: LaTeX reduced to something that can be counted as prose. Deliberately
// shallow: this is not a TeX parser and does not need to be, because every number it
// feeds is compared against other chapters of the SAME document, so whatever it gets
// wrong it gets wrong everywhere and cancels. What it must not do is silently delete
// text (the counts would then describe a document nobody wrote) or keep maths and code
// (which are not sentences and would poison the sentence-length statistics).
export function plainProse(tex) {
    let text = String(tex || '')
    // Comments are already stripped upstream on the review path, but this module is
    // also called on raw sources by its own tests and by anything that reuses it.
    text = text.replace(/(^|[^\\])%[^\n]*/g, '$1')
    text = blankNonProseEnvironments(text)
    text = blankDisplayMaths(text)
    // Inline maths keeps its lazy pattern: it is bounded to 400 characters and to a
    // single line, so an unpaired `$` costs a bounded look-ahead and not a walk to the
    // end of the chapter.
    text = text.replace(/\$[^$\n]{0,400}\$/g, ' ')
    // The argument classes carry the same kind of bound as the inline maths above,
    // and for the same reason: `[^\]]*` after a cheap anchor is a rescan to the end
    // of the chapter for every `\cmd[` that never closes, which on a hostile single-
    // line file is quadratic. With the cap, an argument an author writes is blanked
    // exactly as before; an argument sized like an attack stays visible in the prose,
    // which costs a few noise words instead of the event loop.
    text = text.replace(new RegExp(String.raw`\\(?:${NON_PROSE_COMMANDS})\*?(?:\[[^\]]{0,400}\])?(?:\{[^{}]{0,600}\})*`, 'g'), ' ')
    text = text.replace(/\\(?:begin|end)\{[^{}]{0,200}\}(?:\[[^\]]{0,400}\])?(?:\{[^{}]{0,600}\})?/g, ' ')
    // Whatever is left of a command keeps its braced text: `\textbf{crucial}` is a word
    // the author wrote and the lexical list has to see it.
    text = text.replace(/\\[a-zA-Z@]+\*?(?:\[[^\]]{0,400}\])?/g, ' ')
    text = text.replace(/\\[^a-zA-Z]/g, ' ')
    text = text.replace(/[{}]/g, ' ')
    // Paragraph breaks are load-bearing (clusters are paragraph-local), so blank lines
    // survive while every other run of whitespace collapses.
    text = text.replace(/[^\S\n]+/g, ' ')
    text = text.replace(/\n{3,}/g, '\n\n')
    return text.trim()
}

// Built from a string rather than written as a literal: the apostrophe class holds the
// typographic apostrophe, and this codebase keeps its own sources ASCII.
const WORD = new RegExp("[\\p{L}\\p{N}]+(?:['\\u2019-][\\p{L}\\p{N}]+)*", 'gu')

export function tokenizeWords(text) {
    return String(text || '').match(WORD) || []
}

export function countWords(text) {
    WORD.lastIndex = 0
    let n = 0
    while (WORD.exec(String(text || '')) !== null) {
        n += 1
    }
    return n
}

// overleaf-lab: sentences, to the accuracy the statistics need. An abbreviation splits
// a sentence in two here, and that is tolerable for the same reason the LaTeX
// stripping is shallow: the error is the same in every chapter of the document.
export function splitSentences(text) {
    return String(text || '')
        .split(/(?<=[.!?])\s+|\n{2,}/)
        .map(s => s.trim())
        .filter(s => /[\p{L}\p{N}]/u.test(s))
}

export function splitParagraphs(text) {
    return String(text || '')
        .split(/\n\s*\n/)
        .map(p => p.trim())
        .filter(p => /[\p{L}]/u.test(p))
}

// ---------------------------------------------------------------------------
// robust statistics
// ---------------------------------------------------------------------------

export function median(values) {
    const sorted = values.filter(v => Number.isFinite(v)).sort((a, b) => a - b)
    if (sorted.length === 0) {
        return 0
    }
    const mid = sorted.length >> 1
    return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2
}

export function medianAbsoluteDeviation(values, med = median(values)) {
    return median(values.map(v => Math.abs(v - med)))
}

// overleaf-lab: the scale a deviation is measured in. MAD first; when more than half
// the chapters share one value the MAD is zero and every difference from it scores
// infinite, which would flag a chapter for one em-dash against a document that has
// none. The mean absolute deviation is the fallback, and when that is zero too every
// chapter is identical and there is nothing to say.
export function deviationScale(values) {
    const med = median(values)
    const mad = medianAbsoluteDeviation(values, med)
    if (mad > 0) {
        return { median: med, scale: mad, from: 'mad' }
    }
    const mean = values.reduce((a, b) => a + Math.abs(b - med), 0) / (values.length || 1)
    return { median: med, scale: mean, from: 'mean-absolute-deviation' }
}

export function stdev(values) {
    if (values.length < 2) {
        return 0
    }
    const mean = values.reduce((a, b) => a + b, 0) / values.length
    const variance = values.reduce((a, b) => a + (b - mean) ** 2, 0) / values.length
    return Math.sqrt(variance)
}

// ---------------------------------------------------------------------------
// the signals
// ---------------------------------------------------------------------------

// overleaf-lab: what each signal is, in the words the report prints, plus the smallest
// difference from the median worth printing at all.
//
// `minDelta` is NOT the threshold. The threshold is the robust score; this is a floor
// on the effect size, and it exists because a robust score is a ratio: when the
// chapters of a document agree very closely, a difference far too small to mean
// anything still scores high. Both conditions have to hold.
//
// `minCount` is the second floor and the one that makes "single hits are never
// reported" literally true. A rate is a ratio, and a short chapter with ONE em-dash in
// it has a rate of five per thousand words against a document that has none: without
// this floor the report would point at one dash. Signals that count events carry it;
// the two variation signals measure a shape rather than events and have nothing to
// count.
//
// `direction` says which side of the median is the interesting one, and it is only
// wording: the test is two-tailed either way, because a chapter that deviates the
// other way is still a chapter that does not read like its neighbours.
export const SIGNAL_DEFINITIONS = [
    {
        id: 'emDashPer1000',
        label: 'Em-dashes per 1000 words',
        minDelta: 1,
        countKey: 'emDash',
        minCount: 3,
        note: 'The most heavily measured single tell: em-dash use in preprint abstracts went from 4.23% to 20.3% after 2022. It is also a house style some authors have always had, which is why it is compared against this document rather than against a fixed number.',
    },
    {
        id: 'sentenceLengthVariation',
        label: 'Sentence length variation (standard deviation, in words)',
        minDelta: 1.5,
        direction: 'low',
        note: 'Human prose mixes long and short sentences; generated prose tends to hold one length. A LOW value is the signal.',
    },
    {
        id: 'paragraphLengthVariation',
        label: 'Paragraph length variation (spread relative to the mean)',
        minDelta: 0.15,
        direction: 'low',
        note: 'Paragraphs of near-identical size, one after another. A LOW value is the signal.',
    },
    {
        id: 'connectiveOpeningsPer100Sentences',
        label: 'Sentences opening with a connective, per 100 sentences',
        minDelta: 4,
        countKey: 'openers',
        minCount: 3,
        note: 'However, Moreover, Furthermore, Inoltre, Tuttavia and the rest, counted only where they open a sentence.',
    },
    {
        id: 'tripletsPer1000',
        label: 'Three-item enumerations ("X, Y and Z") per 1000 words',
        minDelta: 1,
        countKey: 'triplets',
        minCount: 3,
    },
    {
        id: 'listItemsPer1000',
        label: 'List items per 1000 words',
        minDelta: 4,
        countKey: 'items',
        minCount: 5,
    },
    {
        id: 'boldLeadItemsPer1000',
        label: 'List items opening with a bold lead-in, per 1000 words',
        minDelta: 1,
        countKey: 'boldItems',
        minCount: 3,
        note: 'The `\\item \\textbf{Term}:` shape, which is what a chat answer looks like once it is pasted into LaTeX.',
    },
    {
        id: 'lexicalMarkersPer1000',
        label: 'Stock-phrase markers per 1000 words',
        minDelta: 1,
        countKey: 'markers',
        minCount: 3,
        note: 'How often the phrases in this version of the pattern list appear, whatever the language.',
    },
]

// overleaf-lab: an em-dash, in both of its spellings. `---` is how LaTeX writes one and
// is what a careful author types; the literal character is what a paste brings in. The
// literal one is also reported on its own as an artifact, so it is counted twice on
// purpose: once as debris, once as style. Built from an escape, never from a literal
// character, because a grep for the literal one over this repository must stay empty.
const EM_DASH = new RegExp('---|\\u2014', 'g')

// Bounded on EVERY side, head and whitespace runs included. The head was
// `[\p{L}\p{N}]+` and the runs were `\s*`: a 64 KB alphanumeric run cost 6.5
// seconds and a run of blank lines before a bold item cost 27, measured, both
// on the event loop. A word before a comma is never 40 characters, and two
// adjacent whitespace runs separated by an optional atom are the same
// backtracking shape however innocent they look: the option consumes the run
// one split at a time. Whitespace is therefore attached INSIDE the optional
// atom, never left adjacent to it.
const TRIPLET = /[\p{L}\p{N}]{1,40}\s{0,10},\s+[^,.;:!?]{2,60}?\s+(?:and|e|ed|or|o)\s+[\p{L}\p{N}]/giu
const ITEM = /\\item(?![a-zA-Z])/g
const BOLD_LEAD_ITEM = /\\item\s{0,40}(?:\[[^\]]{0,80}\]\s{0,40})?\\(?:textbf|textit|emph|bfseries)\s{0,40}\{[^{}]{0,120}\}?\s{0,40}[:.]/g

// overleaf-lab: a short, single-line quotation centred on a hit. Everything the report
// shows from the document goes through here: the reader needs enough to recognise the
// passage and nothing more, and a report that pastes back half a chapter is a report
// that reads as an accusation.
export function excerpt(text, index = 0, length = 0) {
    const flat = String(text || '')
    const start = Math.max(0, index - Math.floor((MAX_EXCERPT_CHARS - length) / 2))
    let slice = flat.slice(start, start + MAX_EXCERPT_CHARS)
    slice = slice.replace(/\s+/g, ' ').trim()
    const prefix = start > 0 ? '...' : ''
    const suffix = start + MAX_EXCERPT_CHARS < flat.length ? '...' : ''
    const room = MAX_EXCERPT_CHARS - prefix.length - suffix.length
    if (slice.length > room) {
        slice = slice.slice(0, room)
    }
    return `${prefix}${slice}${suffix}`
}

// overleaf-lab: WHERE A QUOTED PASSAGE ACTUALLY IS. Until this existed, every passage
// in this section was a quotation with no address: the reader was shown a sentence and
// left to search the project for it, on the one block of the report where the reader is
// explicitly asked to go and judge the passage for themselves.
//
// TWO ROUTES, because the excerpts come from two different texts.
//
// An excerpt cut from the chapter's RAW LaTeX has an offset that means something, and
// the chapter is the parts joined with a known separator, so the file and the line are
// arithmetic: exact, always.
//
// An excerpt cut from the PROSE has an offset that means nothing. `plainProse` blanks
// commands and environments and collapses whitespace, and it says so itself: offsets are
// worth nothing after it. Rebuilding it to preserve them would change what every excerpt
// in this module contains, so instead the passage is FOUND in the source by its own
// words, the way the compliance controller grounds a model's quote.
//
// The rule both routes obey is the module's rule everywhere else: a location is correct
// by construction or it is absent. Nothing here ever guesses a line.
const LOCATE_MIN_CHARS = 16
const LOCATE_MAX_CANDIDATES = 3
// Split on everything a prose reduction could have removed or introduced. What is left
// are runs of letters, digits, spaces, apostrophes and hyphens: characters that pass
// through `plainProse` untouched, so a run of them that is in the excerpt is in the file
// verbatim, whitespace aside. Splitting on the comma too costs a few characters of
// fragment and buys certainty that no fragment straddles a blanked `\textbf{...}`.
const LOCATE_BOUNDARY = /[^\p{L}\p{N}\u2019' -]+/gu

// The searchable form of one file: whitespace runs flattened to a single space, and the
// source line every surviving character came from. Character by character rather than by
// regex, because the line numbers have to be counted in the same pass that flattens.
function foldForSearch(text) {
    const chars = []
    const lines = []
    let line = 1
    let pending = false
    for (let i = 0; i < text.length; i += 1) {
        const code = text.charCodeAt(i)
        const space = code === 32 || code === 9 || code === 10 || code === 13 || code === 11 || code === 12
        if (code === 10) {
            line += 1
        }
        if (space) {
            pending = chars.length > 0
            continue
        }
        if (pending) {
            chars.push(' ')
            lines.push(line)
            pending = false
        }
        chars.push(text[i])
        lines.push(line)
    }
    return { normalized: chars.join(''), lineAt: lines }
}

// overleaf-lab: the file-and-line oracle for one chapter's worth of documents. The
// search index is built ON FIRST USE and not before: a chapter whose signals are all
// unremarkable never has a passage to place, and folding its text would be the whole
// cost of this feature paid for nothing.
export function buildChapterSource(parts) {
    const spans = []
    let offset = 0
    for (const part of Array.isArray(parts) ? parts : []) {
        const text = String(part?.text || '')
        spans.push({
            path: String(part?.path || ''),
            text,
            start: offset,
            end: offset + text.length,
            index: null,
        })
        // The caller joins the parts with a blank line; the two characters are part of
        // the chapter text and therefore part of every offset into it.
        offset += text.length + 2
    }
    return {
        // An offset into the CHAPTER text, which only a raw-derived excerpt has.
        atOffset(at) {
            if (typeof at !== 'number' || !Number.isFinite(at) || at < 0) {
                return null
            }
            for (const span of spans) {
                if (at >= span.start && at <= span.end) {
                    return { file: span.path, line: lineOf(span.text, at - span.start) }
                }
            }
            return null
        },
        // A passage, by its words. Longest fragment first, because a long run of words is
        // far less likely to occur twice in a thesis than a short one.
        find(passage) {
            const fragments = String(passage || '')
                .split(LOCATE_BOUNDARY)
                .map(piece => piece.replace(/\s+/g, ' ').trim())
                .filter(piece => piece.length >= LOCATE_MIN_CHARS)
                .sort((a, b) => b.length - a.length)
                .slice(0, LOCATE_MAX_CANDIDATES)
            for (const fragment of fragments) {
                for (const span of spans) {
                    if (!span.index) {
                        span.index = foldForSearch(span.text)
                    }
                    const at = span.index.normalized.indexOf(fragment)
                    if (at !== -1) {
                        return { file: span.path, line: span.index.lineAt[at] }
                    }
                }
            }
            return null
        },
    }
}

// overleaf-lab: every lexical hit in a text, with overlapping hits resolved to one.
// Without this, "riveste un ruolo cruciale" counts as two markers (the phrase and the
// bare "cruciale" inside it) and a paragraph reaches the cluster threshold on a single
// turn of phrase, which is exactly what the threshold exists to prevent. The longest
// match at a position wins.
export function lexicalMatches(text, patterns = LEXICAL) {
    const raw = []
    for (const pattern of patterns) {
        pattern.regex.lastIndex = 0
        let match
        while ((match = pattern.regex.exec(text)) !== null) {
            raw.push({ id: pattern.id, label: pattern.label, lang: pattern.lang, index: match.index, text: match[0] })
            if (match[0].length === 0) {
                pattern.regex.lastIndex += 1
            }
        }
    }
    raw.sort((a, b) => a.index - b.index || b.text.length - a.text.length)
    const kept = []
    let usedTo = -1
    for (const hit of raw) {
        if (hit.index < usedTo) {
            continue
        }
        kept.push(hit)
        usedTo = hit.index + hit.text.length
    }
    return kept
}

// overleaf-lab: every number this module knows how to compute about one chapter.
// `text` is the chapter's LaTeX; some signals are counted on it (`\item` does not
// survive the prose reduction) and the rest on the prose.
// `source` is the oracle from buildChapterSource, and it is OPTIONAL: this function is
// also called by its own tests and by anything reusing the module on a bare string, and
// an excerpt with no location is exactly what this block produced before locations
// existed. Absent, every excerpt is stored with its text and nothing else.
export function computeChapterMetrics(chapter, source = null) {
    const name = String(chapter?.name || chapter?.title || 'Untitled')
    const raw = String(chapter?.text || '')
    const prose = plainProse(raw)
    const words = countWords(prose)
    const sentences = splitSentences(prose)
    const paragraphs = splitParagraphs(prose)
    const per1000 = n => (words > 0 ? (n * 1000) / words : 0)

    const evidence = {}
    // overleaf-lab: an excerpt is now `{ text, file, line }` instead of a bare string.
    // ADDITIVE: `text` holds exactly what the string used to hold, so a renderer that
    // reads one shape reads the other with a one-line normalisation, and a block stored
    // before this change still renders. `file` and `line` are simply absent when the
    // passage could not be placed, which is the honest answer and never a guess.
    //
    // WHICH ROUTE, decided here and nowhere else: a passage cut from the chapter's raw
    // LaTeX carries a meaningful offset, so it is placed by arithmetic; one cut from the
    // prose or from a single sentence carries none, so it is placed by its own words.
    const collect = (id, text, index, length) => {
        if (!evidence[id]) {
            evidence[id] = []
        }
        if (evidence[id].length >= MAX_EXCERPTS_PER_SIGNAL) {
            return
        }
        const quoted = excerpt(text, index, length)
        const at = !source ? null : text === raw ? source.atOffset(index) : source.find(quoted)
        evidence[id].push(at ? { text: quoted, file: at.file, line: at.line } : { text: quoted })
    }

    let emDashes = 0
    EM_DASH.lastIndex = 0
    let hit
    while ((hit = EM_DASH.exec(raw)) !== null) {
        emDashes += 1
        collect('emDashPer1000', raw, hit.index, hit[0].length)
    }

    let triplets = 0
    TRIPLET.lastIndex = 0
    while ((hit = TRIPLET.exec(prose)) !== null) {
        triplets += 1
        collect('tripletsPer1000', prose, hit.index, hit[0].length)
    }

    let items = 0
    ITEM.lastIndex = 0
    while ((hit = ITEM.exec(raw)) !== null) {
        items += 1
        collect('listItemsPer1000', raw, hit.index, hit[0].length)
    }

    let boldItems = 0
    BOLD_LEAD_ITEM.lastIndex = 0
    while ((hit = BOLD_LEAD_ITEM.exec(raw)) !== null) {
        boldItems += 1
        collect('boldLeadItemsPer1000', raw, hit.index, hit[0].length)
    }

    let openers = 0
    for (const sentence of sentences) {
        if (OPENER_PATTERN.test(sentence)) {
            openers += 1
            collect('connectiveOpeningsPer100Sentences', sentence, 0, Math.min(40, sentence.length))
        }
    }

    const markers = lexicalMatches(prose)
    for (const marker of markers.slice(0, MAX_EXCERPTS_PER_SIGNAL)) {
        collect('lexicalMarkersPer1000', prose, marker.index, marker.text.length)
    }

    const sentenceWords = sentences.map(s => countWords(s))
    const paragraphWords = paragraphs.map(p => countWords(p))
    const paragraphMean = paragraphWords.length ? paragraphWords.reduce((a, b) => a + b, 0) / paragraphWords.length : 0

    return {
        name,
        words,
        prose,
        sentences: sentences.length,
        paragraphs: paragraphs.length,
        markers,
        evidence,
        // The raw event counts behind the rates. A rate alone cannot say whether it
        // came from one occurrence or forty, and the difference decides whether
        // anything is reported at all.
        counts: {
            emDash: emDashes,
            triplets,
            items,
            boldItems,
            openers,
            markers: markers.length,
        },
        signals: {
            emDashPer1000: per1000(emDashes),
            // Fewer than three sentences is not a distribution; reporting a spread for
            // it would be reporting noise, so the signal is simply absent.
            sentenceLengthVariation: sentenceWords.length >= 3 ? stdev(sentenceWords) : null,
            paragraphLengthVariation:
                paragraphWords.length >= 3 && paragraphMean > 0 ? stdev(paragraphWords) / paragraphMean : null,
            connectiveOpeningsPer100Sentences: sentences.length >= 5 ? (openers * 100) / sentences.length : null,
            tripletsPer1000: per1000(triplets),
            listItemsPer1000: per1000(items),
            boldLeadItemsPer1000: per1000(boldItems),
            lexicalMarkersPer1000: per1000(markers.length),
        },
    }
}

// ---------------------------------------------------------------------------
// artifacts
// ---------------------------------------------------------------------------

function lineOf(text, index) {
    let line = 1
    for (let i = 0; i < index && i < text.length; i++) {
        if (text[i] === '\n') {
            line += 1
        }
    }
    return line
}

// overleaf-lab: artifacts, one row per pattern and file, with a count rather than one
// row per occurrence. A thesis pasted out of a word processor carries hundreds of
// typographic quotes and would otherwise fill the report with the same row.
//
// The scan always runs to the end of every file: `occurrences` is the real number, and
// the cap applies only to how many ROWS are kept.
export function findArtifacts(docs, patterns = ARTIFACTS) {
    const rows = []
    for (const pattern of patterns) {
        for (const doc of docs || []) {
            const text = String(doc?.text || '')
            pattern.regex.lastIndex = 0
            let count = 0
            let first = null
            let match
            while ((match = pattern.regex.exec(text)) !== null) {
                count += 1
                if (!first) {
                    first = match
                }
                if (match[0].length === 0) {
                    pattern.regex.lastIndex += 1
                }
            }
            if (count > 0) {
                rows.push({
                    id: pattern.id,
                    pattern: pattern.source,
                    label: pattern.label,
                    kind: pattern.kind || 'tool',
                    file: String(doc?.path || doc?.name || ''),
                    line: lineOf(text, first.index),
                    occurrences: count,
                    excerpt: excerpt(text, first.index, first[0].length),
                })
            }
        }
    }
    const order = { tool: 0, paste: 1 }
    rows.sort(
        (a, b) =>
            (order[a.kind] ?? 9) - (order[b.kind] ?? 9) || b.occurrences - a.occurrences || a.file.localeCompare(b.file)
    )
    return { artifacts: rows.slice(0, MAX_ARTIFACT_ROWS), total: rows.length }
}

// ---------------------------------------------------------------------------
// clusters
// ---------------------------------------------------------------------------

// overleaf-lab: paragraphs of ONE chapter holding CLUSTER_MIN_MARKERS or more DISTINCT
// markers. The count is of distinct ids, never of hits: a paragraph that says "crucial"
// three times is a paragraph about something crucial.
//
// Per chapter, and pushing into a sink the caller owns, so the entry point can run this
// while the chapter's prose is in hand and then let that prose go. Every paragraph is
// examined even after the sink is full; what stops is the storing, not the counting.
export function collectClusters(name, prose, sink, source = null) {
    let total = 0
    for (const paragraph of splitParagraphs(prose)) {
        const distinct = new Map()
        for (const hit of lexicalMatches(paragraph)) {
            if (!distinct.has(hit.id)) {
                distinct.set(hit.id, hit)
            }
        }
        if (distinct.size < CLUSTER_MIN_MARKERS) {
            continue
        }
        total += 1
        if (sink.length >= MAX_CLUSTERS) {
            continue
        }
        const ordered = [...distinct.values()].sort((a, b) => a.index - b.index)
        const quoted = excerpt(paragraph, ordered[0].index, ordered[0].text.length)
        // A paragraph is cut out of the PROSE, so its offset says nothing about the
        // file: the passage is placed by its own words or not at all. `paragraphExcerpt`
        // keeps its name and its contents, so a block stored before this change and a
        // block stored after it render through the same path.
        const at = source ? source.find(quoted) : null
        sink.push({
            chapter: name,
            paragraphExcerpt: quoted,
            ...(at ? { file: at.file, line: at.line } : {}),
            markers: ordered.slice(0, MAX_CLUSTER_MARKERS).map(h => h.label),
            markersTotal: ordered.length,
        })
    }
    return total
}

// overleaf-lab: the same pass over a whole document, for callers that already hold
// every chapter (the tests, and anything reusing this module outside the review).
export function findClusters(chapterMetrics) {
    const clusters = []
    let total = 0
    for (const chapter of chapterMetrics || []) {
        const prose = chapter.prose || plainProse(chapter.text)
        if (!prose) {
            continue
        }
        total += collectClusters(chapter.name, prose, clusters)
    }
    return { clusters, total }
}

// ---------------------------------------------------------------------------
// aggregation
// ---------------------------------------------------------------------------

function round(value) {
    return Math.round(value * 100) / 100
}

// overleaf-lab: which chapters deviate from the document's own median, per signal.
export function flagDeviations(chapterMetrics, options = {}) {
    const threshold = options.threshold ?? ROBUST_SCORE_THRESHOLD
    const minChapters = options.minChapters ?? MIN_CHAPTERS_FOR_BASELINE
    const minWords = options.minWords ?? MIN_CHAPTER_WORDS
    const eligible = (chapterMetrics || []).filter(c => c.words >= minWords)
    if (eligible.length < minChapters) {
        return { compared: eligible.length, flagged: [] }
    }
    const byChapter = new Map()
    for (const definition of SIGNAL_DEFINITIONS) {
        const present = eligible.filter(c => Number.isFinite(c.signals[definition.id]))
        if (present.length < minChapters) {
            continue
        }
        const values = present.map(c => c.signals[definition.id])
        const { median: med, scale } = deviationScale(values)
        if (!(scale > 0)) {
            continue
        }
        for (const chapter of present) {
            const value = chapter.signals[definition.id]
            const delta = Math.abs(value - med)
            if (delta < definition.minDelta) {
                continue
            }
            if (definition.countKey && (chapter.counts?.[definition.countKey] || 0) < definition.minCount) {
                continue
            }
            if (delta / scale <= threshold) {
                continue
            }
            if (!byChapter.has(chapter.name)) {
                byChapter.set(chapter.name, [])
            }
            const excerpts = chapter.evidence[definition.id] || []
            byChapter.get(chapter.name).push({
                id: definition.id,
                label: definition.label,
                value: round(value),
                thesisMedian: round(med),
                robustScore: round(delta / scale),
                direction: value > med ? 'above' : 'below',
                excerpts,
                // What the excerpts are a sample OF. The scan counted every occurrence
                // in the chapter; only this many were kept.
                excerptsTotal: definition.countKey
                    ? chapter.counts?.[definition.countKey] || excerpts.length
                    : excerpts.length,
            })
        }
    }
    const all = [...byChapter.entries()].map(([name, signals]) => ({
        name,
        signals: signals.sort((a, b) => b.robustScore - a.robustScore),
    }))
    all.sort((a, b) => b.signals.length - a.signals.length || a.name.localeCompare(b.name))
    // The cap is on signal ROWS, and it is spent on the chapters that deviate most,
    // which is the order the list is already in.
    const flagged = []
    let budget = options.maxSignals ?? MAX_FLAGGED_SIGNALS
    for (const chapter of all) {
        if (budget <= 0) {
            break
        }
        const signals = chapter.signals.slice(0, budget)
        budget -= signals.length
        flagged.push({ name: chapter.name, signals })
    }
    return {
        compared: eligible.length,
        flagged,
        totalChapters: all.length,
        totalSignals: all.reduce((n, c) => n + c.signals.length, 0),
        shownSignals: flagged.reduce((n, c) => n + c.signals.length, 0),
    }
}

// ---------------------------------------------------------------------------
// entry point
// ---------------------------------------------------------------------------

// overleaf-lab: the whole section, from the chapters the review already cut.
//
// INPUT, in the shape the caller happens to have: an array of chapters, each
// `{ name, text }` or `{ name, docs: [{ path, text }] }`. The second form is what the
// controller holds after segmentation and is worth passing, because it is what lets an
// artifact be reported against the file it is actually in rather than against the
// chapter that spans three files.
//
// OUTPUT: a JSON-able block, safe to store on the result object and safe to render.
// Counts and values only. There is no score for the document, no probability, and
// nothing in it that names a person. Every list in it is bounded and every bound is
// stated next to the true total, because this block is stored three times over (job
// result, Mongo document, archived HTML) and a pathological upload must not be able to
// grow any of them without limit.
//
// THE UNIT OF WORK IS THE CHAPTER. Nothing here ever holds the whole document: a
// chapter's prose exists while that chapter is measured and is dropped before the next
// one, and the baseline that follows is computed over per-chapter NUMBERS. The peak
// cost is therefore the largest single chapter, not the thesis.
export function analyzeAiWritingSignals(chapters, options = {}) {
    const input = Array.isArray(chapters) ? chapters : []
    const docs = []
    const metrics = []
    const clusters = []
    let clustersTotal = 0
    let words = 0

    for (const chapter of input) {
        const parts =
            Array.isArray(chapter?.docs) && chapter.docs.length
                ? chapter.docs.map(d => ({ path: String(d?.path || ''), text: String(d?.text || '') }))
                : [
                      {
                          path: String(chapter?.file || chapter?.path || chapter?.name || ''),
                          text: String(chapter?.text || ''),
                      },
                  ]
        for (const part of parts) {
            docs.push(part)
        }
        // overleaf-lab: a chapter the caller marks `standalone` is not prose. In the
        // review that is a .bib or another non-source file, segmented on its own
        // because it belongs to no chapter; measured as prose it is a few thousand
        // author names with no sentences, and letting it into the median makes every
        // real chapter look like an outlier. It is still scanned for artifacts, since a
        // chatgpt.com tracking parameter in a bibliography is exactly the kind of thing
        // this section exists to show.
        if (chapter?.standalone) {
            continue
        }
        const text = parts.map(p => p.text).join('\n\n')
        if (!text.trim()) {
            continue
        }
        // The oracle that turns this chapter's passages into file:line. It is built per
        // chapter and dropped with the chapter, so the peak stays at one chapter here as
        // it does everywhere else in this function, and its own index is built only if a
        // passage actually has to be placed.
        const source = buildChapterSource(parts)
        const metric = computeChapterMetrics({ name: chapter?.name || chapter?.title, text }, source)
        clustersTotal += collectClusters(metric.name, metric.prose, clusters, source)
        // The prose and the match list of a chapter are the two big objects here, and
        // neither is needed again: the baseline works on the numbers. Dropping them
        // keeps the peak at one chapter rather than at one thesis.
        delete metric.prose
        delete metric.markers
        metrics.push(metric)
        words += metric.words
    }

    const artifacts = findArtifacts(docs)
    const deviations = flagDeviations(metrics, options)
    const legendIds = new Set(deviations.flagged.flatMap(c => c.signals.map(s => s.id)))

    return {
        version: AI_SIGNALS_VERSION,
        totals: {
            words,
            chapters: metrics.length,
            comparedChapters: deviations.compared,
            minChapters: options.minChapters ?? MIN_CHAPTERS_FOR_BASELINE,
            // shown vs total for every list that can be cut short, so the report can
            // say how much it is not showing.
            artifacts: { shown: artifacts.artifacts.length, total: artifacts.total },
            flaggedChapters: { shown: deviations.flagged.length, total: deviations.totalChapters },
            flaggedSignals: { shown: deviations.shownSignals, total: deviations.totalSignals },
            clusters: { shown: clusters.length, total: clustersTotal },
        },
        artifacts: artifacts.artifacts,
        flaggedChapters: deviations.flagged,
        clusters,
        // What each flagged signal means, once per signal instead of once per chapter:
        // the same paragraph of explanation repeated on thirty rows is most of the
        // weight of a large block.
        legend: SIGNAL_DEFINITIONS.filter(d => legendIds.has(d.id) && d.note).map(d => ({
            id: d.id,
            label: d.label,
            note: d.note,
        })),
    }
}

// overleaf-lab: is there anything to show at all. The renderer asks this so that a
// clean thesis gets no section, not an empty one: a heading that says "AI writing
// signals" over the words "nothing found" still puts the question in the document.
export function hasAiSignals(block) {
    return Boolean(
        block &&
            ((block.artifacts && block.artifacts.length) ||
                (block.flaggedChapters && block.flaggedChapters.length) ||
                (block.clusters && block.clusters.length))
    )
}

export default {
    AI_SIGNALS_VERSION,
    MIN_CHAPTERS_FOR_BASELINE,
    MIN_CHAPTER_WORDS,
    ROBUST_SCORE_THRESHOLD,
    CLUSTER_MIN_MARKERS,
    LIMITS,
    SIGNAL_DEFINITIONS,
    analyzeAiWritingSignals,
    hasAiSignals,
    buildChapterSource,
    compilePatterns,
    computeChapterMetrics,
    findArtifacts,
    findClusters,
    collectClusters,
    flagDeviations,
    lexicalMatches,
    plainProse,
    splitSentences,
    splitParagraphs,
    tokenizeWords,
    countWords,
    excerpt,
    median,
    medianAbsoluteDeviation,
    deviationScale,
    stdev,
}
